    public function dashboard(Request $request){
        $ownerId=$request->user()->id;
        $stats=['Pickup Requests'=>Shipment::where('status','ready_for_pickup')->count(),'Incoming Parcels'=>Shipment::where('status','picked_up')->count(),'Awaiting Sorting'=>Shipment::where('status','at_sorting_center')->count(),'Awaiting Assignment'=>Shipment::where('status','sorted')->count(),'Out for Delivery'=>Shipment::where('status','out_for_delivery')->count(),'Delivery Failed'=>Shipment::where('status','delivery_failed')->count(),'Delivered Today'=>Shipment::whereIn('status',['delivered','completed'])->whereDate('delivered_at',today())->count(),'Available Riders'=>RiderProfile::where('logistics_user_id',$ownerId)->where('account_status','active')->where('availability','available')->count()];
        $recent=Shipment::with(['store','pickupRider','rider','deliveryArea'])->latest('updated_at')->limit(12)->get();
        $riderStats=['available'=>RiderProfile::where('logistics_user_id',$ownerId)->where('account_status','active')->where('availability','available')->count(),'assigned'=>RiderProfile::where('logistics_user_id',$ownerId)->whereIn('availability',['assigned','on_delivery'])->count(),'unavailable'=>RiderProfile::where('logistics_user_id',$ownerId)->whereIn('availability',['off_duty','unavailable'])->count()];
        return view('logistics.dashboard',compact('stats','recent','riderStats'));
    }
    public function quickCreateLoad(Request $r,ShipmentService $service){$d=$r->validate(['seller_order_id'=>'required|exists:seller_orders,id']);$shipment=$service->createForSellerOrder(SellerOrder::findOrFail($d['seller_order_id']),$r->user());return redirect()->route('logistics.shipments.index',['view'=>$shipment->id])->with('success','Load created from the ready-to-ship Seller Order.');}
    public function quickInvoice(Request $r){$d=$r->validate(['shipment_id'=>'required|exists:shipments,id']);$invoice=DB::transaction(function()use($d){$load=Shipment::with('sellerOrder')->whereKey($d['shipment_id'])->lockForUpdate()->firstOrFail();return LogisticsInvoice::firstOrCreate(['shipment_id'=>$load->id],['invoice_number'=>LogisticsInvoice::number(),'delivery_fee'=>$load->sellerOrder->shipping_fee,'adjustments'=>0,'total'=>$load->sellerOrder->shipping_fee,'status'=>'issued','due_at'=>now()->addDays(30),'notes'=>'Generated from the existing Load delivery fee.']);});$message=$invoice->wasRecentlyCreated?'Logistics invoice generated.':'An invoice already exists for this Load.';return redirect()->route('logistics.billing',['view'=>$invoice->id])->with('success',$message);}
    protected function shipmentQuery(Request $r){return Shipment::with(['order','sellerOrder.items','store.user','rider','vehicle','proofOfDelivery'])->when($r->q,fn($q,$v)=>$q->where(fn($x)=>$x->where('shipment_number','like',"%$v%")->orWhereHas('order',fn($o)=>$o->where('order_number','like',"%$v%"))->orWhereHas('sellerOrder',fn($s)=>$s->where('seller_order_number','like',"%$v%"))->orWhereHas('store',fn($s)=>$s->where('name','like',"%$v%"))))->when($r->status,fn($q,$v)=>$q->where('status',$v))->when($r->rider_id,fn($q,$v)=>$q->where('rider_id',$v))->when($r->vehicle_id,fn($q,$v)=>$q->where('vehicle_id',$v));}
    public function shipments(Request $r){$shipments=$this->shipmentQuery($r)->when($r->shop_id,fn($q,$v)=>$q->where('store_id',$v))->when($r->date_from,fn($q,$v)=>$q->whereDate('created_at','>=',$v))->when($r->date_to,fn($q,$v)=>$q->whereDate('created_at','<=',$v))->latest()->paginate(20)->withQueryString();$riders=User::where('is_active',true)->whereHas('roles',fn($q)=>$q->where('slug','rider'))->whereHas('riderProfile',fn($q)=>$q->where('logistics_user_id',$r->user()->id)->assignmentEligible())->orderBy('name')->get();$vehicles=Vehicle::orderBy('code')->get();$shops=\App\Models\Store::orderBy('name')->get();$selected=$r->view?Shipment::with(['order.user','sellerOrder.items.product','store.user','rider.riderProfile','vehicle','currentHub','events.actor','assignments.rider','assignments.vehicle','proofOfDelivery','invoice'])->find($r->view):null;$hubs=LogisticsHub::where('status','active')->get();return view('logistics.shipments',compact('shipments','riders','vehicles','shops','selected','hubs'));}
    public function show(Shipment $shipment){$shipment->load(['order.user','sellerOrder.items.product','sellerOrder.items.variant','store.user','rider.riderProfile','vehicle','currentHub','events.actor.roles','assignments.rider','assignments.vehicle','proofOfDelivery','invoice']);$hubs=LogisticsHub::where('status','active')->get();return view('logistics.shipment-show',compact('shipment','hubs'));}
    public function dispatch(Request $request){ $shipments=Shipment::with(['store','rider','vehicle'])->latest()->get()->groupBy('status');$riders=User::where('is_active',true)->whereHas('roles',fn($q)=>$q->where('slug','rider'))->whereHas('riderProfile',fn($q)=>$q->where('logistics_user_id',$request->user()->id)->assignmentEligible())->get();$vehicles=Vehicle::where('status','available')->get();return view('logistics.dispatch',compact('shipments','riders','vehicles')); }
    public function assign(Request $r,Shipment $shipment,ShipmentService $service){$d=$r->validate(['rider_id'=>'required|exists:users,id','vehicle_id'=>'nullable|exists:vehicles,id','reason'=>'nullable|string|max:500']);$service->assign($shipment,$r->user(),User::findOrFail($d['rider_id']),isset($d['vehicle_id'])?Vehicle::find($d['vehicle_id']):null,$d['reason']??null);return back()->with('success','Shipment assignment saved.');}
    public function status(Request $r,Shipment $shipment,ShipmentService $service){$d=$r->validate(['status'=>'required|in:'.implode(',',Shipment::STATUSES),'note'=>'nullable|string|max:500']);$service->transition($shipment,$r->user(),$d['status'],$d['note']??null);return back()->with('success','Shipment status updated.');}
    public function tracking(Request $r){$relations=['pickupRider.riderProfile','rider.riderProfile','deliveryArea','events.actor.roles'];$shipments=$this->shipmentQuery($r)->with($relations)->latest('updated_at')->paginate(20)->withQueryString();$selected=$r->shipment?Shipment::with(array_merge(['order.user','store'],$relations))->find($r->shipment):$shipments->first()?->load(array_merge(['order.user','store'],$relations));return view('logistics.tracking',compact('shipments','selected'));}
    public function fleet(Request $r){$query=Vehicle::with(['hub','shipments.rider'])->when($r->q,fn($q,$v)=>$q->where(fn($x)=>$x->where('code','like',"%$v%")->orWhere('plate_number','like',"%$v%")->orWhere('make','like',"%$v%")->orWhere('model','like',"%$v%")))->when($r->type,fn($q,$v)=>$q->where('type',$v))->when($r->status,fn($q,$v)=>$q->where('status',$v))->when($r->hub_id,fn($q,$v)=>$q->where('hub_id',$v));$stats=['total'=>(clone $query)->count(),'available'=>(clone $query)->where('status','available')->count(),'in_use'=>(clone $query)->where('status','in_use')->count(),'maintenance'=>(clone $query)->where('status','maintenance')->count()];$vehicles=$query->latest()->paginate(20)->withQueryString();$selected=$r->view?Vehicle::with(['hub','shipments.rider'])->find($r->view):null;$hubs=LogisticsHub::where('status','active')->get();return view('logistics.fleet',compact('vehicles','hubs','stats','selected')); }
    public function vehicleStore(Request $r){Vehicle::create($r->validate(['code'=>'required|string|max:40|unique:vehicles','plate_number'=>'nullable|string|max:40|unique:vehicles','type'=>'required|in:motorcycle,scooter,tricycle,car,van,delivery_truck,other','make'=>'nullable|string|max:80','model'=>'nullable|string|max:80','year'=>'nullable|integer|min:1990|max:'.(now()->year+1),'capacity_kg'=>'nullable|numeric|min:0','hub_id'=>'nullable|exists:logistics_hubs,id','status'=>'required|in:available,in_use,maintenance,unavailable,retired','notes'=>'nullable|string|max:1000']));return back()->with('success','Vehicle saved.');}
    public function vehicleStatus(Request $r,Vehicle $vehicle){$d=$r->validate(['status'=>'required|in:available,maintenance,unavailable,retired','notes'=>'nullable|string|max:1000']);abort_if($vehicle->status==='in_use',422,'End the active shipment assignment first.');$vehicle->update($d);return back()->with('success','Vehicle status updated.');}
    public function riders(Request $r)
    {
        $ownerId=$r->user()->id;
        $approved=fn($q)=>$q->where(fn($u)=>$u->where('registration_status','approved')->orWhereNull('registration_status'));
        $workforce=RiderProfile::query()->where('logistics_user_id',$ownerId)->whereHas('user',$approved);
        $query=RiderProfile::with(['user.addresses','hub','vehicle','deliveryAreas','logisticsOwner'])->where('logistics_user_id',$ownerId)->whereHas('user',$approved)
            ->when($r->status==='suspended',fn($q)=>$q->where('account_status','suspended'))
            ->when(in_array($r->status,['available','assigned','on_pickup','on_delivery','off_duty','unavailable'],true),fn($q)=>$q->where('availability',$r->status))
            ->when($r->q,fn($q,$v)=>$q->where(fn($x)=>$x->whereHas('user',fn($u)=>$u->where('name','like',"%$v%")->orWhere('email','like',"%$v%")->orWhere('phone','like',"%$v%"))->orWhereHas('vehicle',fn($vehicle)=>$vehicle->where('code','like',"%$v%")->orWhere('plate_number','like',"%$v%"))))
            ->when($r->account_status,fn($q,$v)=>$q->where('account_status',$v))->when($r->availability,fn($q,$v)=>$q->where('availability',$v))->when($r->hub_id,fn($q,$v)=>$q->where('hub_id',$v))->when($r->license_status,fn($q,$v)=>$q->where('driver_license_status',$v));
        $stats=['active'=>(clone $workforce)->where('account_status','active')->count(),'available'=>(clone $workforce)->where('account_status','active')->where('availability','available')->count(),'pickup'=>(clone $workforce)->where('availability','on_pickup')->count(),'delivery'=>(clone $workforce)->where('availability','on_delivery')->count(),'unavailable'=>(clone $workforce)->whereIn('availability',['off_duty','unavailable'])->count(),'license_attention'=>(clone $workforce)->where(fn($q)=>$q->where('driver_license_status','!=','verified')->orWhereDate('driver_license_expires_at','<=',now()->addDays(config('riders.license_expiry_warning_days',30))))->count()];
        $filterCounts=[''=>(clone $workforce)->count(),'available'=>(clone $workforce)->where('availability','available')->count(),'assigned'=>(clone $workforce)->where('availability','assigned')->count(),'on_pickup'=>(clone $workforce)->where('availability','on_pickup')->count(),'on_delivery'=>(clone $workforce)->where('availability','on_delivery')->count(),'off_duty'=>(clone $workforce)->where('availability','off_duty')->count(),'unavailable'=>(clone $workforce)->where('availability','unavailable')->count(),'suspended'=>(clone $workforce)->where('account_status','suspended')->count()];
        $riders=$query->latest()->paginate(20)->withQueryString();
        $selected=$r->view?RiderProfile::with(['user.addresses','hub','vehicle','deliveryAreas','licenseReviewer','licenseAudits.actor','logisticsOwner'])->where('logistics_user_id',$ownerId)->find($r->view):null;
        if($r->view&&!$selected)abort(404);
        $selectedShipments=$selected?Shipment::with(['store','vehicle','proofOfDelivery','order.payments'])->where(fn($q)=>$q->where('rider_id',$selected->user_id)->orWhere('pickup_rider_id',$selected->user_id))->latest()->limit(20)->get():collect();
        $profileIds=$riders->getCollection()->pluck('user_id');$currentAssignments=Shipment::with(['store','vehicle','deliveryArea'])->where(fn($q)=>$q->whereIn('rider_id',$profileIds)->orWhereIn('pickup_rider_id',$profileIds))->whereNotIn('status',['delivered','returned','completed'])->latest('updated_at')->get();
        $hubs=LogisticsHub::where('status','active')->get();$vehicles=Vehicle::whereIn('status',['available','in_use'])->orderBy('code')->get();$deliveryAreas=\App\Models\DeliveryArea::where('is_active',true)->orderBy('name')->get();
        return view('logistics.riders',compact('riders','hubs','vehicles','deliveryAreas','stats','filterCounts','selected','selectedShipments','currentAssignments'));
    }
    public function riderApplications(Request $r)
    {
        $base=RiderProfile::query()->whereHas('user',fn($q)=>$q->where('registration_type','rider'));
        $stats=['pending'=>(clone $base)->whereHas('user',fn($q)=>$q->where('registration_status','pending'))->count(),'needs_resubmission'=>(clone $base)->whereHas('user',fn($q)=>$q->where('registration_status','needs_resubmission'))->count(),'approved_today'=>(clone $base)->whereHas('user',fn($q)=>$q->where('registration_status','approved')->whereDate('registration_reviewed_at',today()))->count(),'rejected'=>(clone $base)->whereHas('user',fn($q)=>$q->where('registration_status','rejected'))->count()];
        $status=$r->input('status','pending');
        $applications=RiderProfile::with(['user.addresses'])->whereHas('user',fn($q)=>$q->where('registration_type','rider')->when($status,fn($u)=>$u->where('registration_status',$status)))->when($r->q,fn($q,$v)=>$q->whereHas('user',fn($u)=>$u->where('name','like',"%$v%")->orWhere('email','like',"%$v%")->orWhere('phone','like',"%$v%")))->when($r->date_from,fn($q,$v)=>$q->whereDate('created_at','>=',$v))->when($r->date_to,fn($q,$v)=>$q->whereDate('created_at','<=',$v))->latest()->paginate(20)->withQueryString();
        $selected=$r->view?RiderProfile::with(['user.addresses','licenseReviewer','licenseAudits.actor'])->whereHas('user',fn($q)=>$q->where('registration_type','rider'))->find($r->view):null;
        return view('logistics.rider-applications',compact('applications','selected','stats','status'));
    }
    public function riderStore(Request $r,RiderActivationService $activation)
    {
        $r->merge(['email'=>mb_strtolower(trim((string)$r->input('email'))),'phone'=>trim((string)$r->input('phone')),'driver_license_number'=>strtoupper(trim((string)$r->input('driver_license_number'))),'plate_number'=>strtoupper(trim((string)$r->input('plate_number')))]);
        $max=config('riders.document_max_kilobytes',5120);
        $d=$r->validate([
            'first_name'=>'required|string|max:100','middle_initial'=>'nullable|string|max:5','last_name'=>'required|string|max:100',
            'birthday'=>'required|date|before_or_equal:today','email'=>['required','email','max:255',function($attribute,$value,$fail){if(User::withTrashed()->whereRaw('LOWER(email) = ?', [mb_strtolower(trim((string)$value))])->exists())$fail('This email address is already in use.');}],'phone'=>'required|string|max:30|unique:users,phone',
            'driver_license_number'=>['required','string','min:5','max:80','regex:/^[A-Za-z0-9 .\/-]+$/','unique:rider_profiles,driver_license_number'],
            'driver_license_expires_at'=>'required|date','vehicle_type'=>'required|string|max:60','plate_number'=>'required|string|max:40|unique:rider_profiles,plate_number',
            'driver_license'=>'required|file|mimes:pdf,jpg,jpeg,png|max:'.$max,'or_cr'=>'required|file|mimes:pdf,jpg,jpeg,png|max:'.$max,
            'hub_id'=>'nullable|exists:logistics_hubs,id','emergency_contact_name'=>'nullable|string|max:100','emergency_contact_phone'=>'nullable|string|max:30',
        ],['birthday.before_or_equal'=>'Date of birth cannot be in the future.']);

        try{$profile=DB::transaction(function()use($d,$r){
            $name=trim($d['first_name'].' '.(($d['middle_initial']??null)?$d['middle_initial'].'. ':'').$d['last_name']);
            $user=User::create(['name'=>$name,'first_name'=>$d['first_name'],'middle_initial'=>$d['middle_initial']??null,'last_name'=>$d['last_name'],'birthday'=>$d['birthday'],'email'=>$d['email'],'phone'=>$d['phone'],'password'=>Hash::make(\Illuminate\Support\Str::random(48)),'registration_type'=>'rider','registration_status'=>'approved','is_active'=>false]);
            $user->assignRole('rider');
            $license=$r->file('driver_license')->store('rider-documents/licenses','local');
            $profile=RiderProfile::create(['user_id'=>$user->id,'logistics_user_id'=>$r->user()->id,'hub_id'=>$d['hub_id']??null,'account_status'=>'pending_activation','availability'=>'unavailable','emergency_contact_name'=>$d['emergency_contact_name']??null,'emergency_contact_phone'=>$d['emergency_contact_phone']??null,'driver_license_number'=>$d['driver_license_number'],'driver_license_expires_at'=>$d['driver_license_expires_at'],'vehicle_type'=>$d['vehicle_type'],'plate_number'=>$d['plate_number'],'driver_license_path'=>$license,'driver_license_front_path'=>$license,'or_cr_path'=>$r->file('or_cr')->store('rider-documents/vehicles','local'),'driver_license_status'=>'pending_review']);
            $profile->licenseAudits()->create(['actor_id'=>$r->user()->id,'event'=>'uploaded','status'=>'pending_review','metadata'=>['expiration'=>$d['driver_license_expires_at']]]);
            return $profile->load(['user','logisticsOwner']);
        });}catch(\Illuminate\Database\UniqueConstraintViolationException $exception){if(User::withTrashed()->whereRaw('LOWER(email) = ?',[$d['email']])->exists())throw ValidationException::withMessages(['email'=>'This email address is already in use.']);throw $exception;}
        try{$activation->send($profile);return back()->with('success','Rider created as Pending Activation. Activation email sent to '.$profile->user->email.'.');}
        catch(\Throwable $e){\Illuminate\Support\Facades\Log::warning('Rider activation email delivery failed.',['rider_profile_id'=>$profile->id]);return back()->with('warning','Rider created as Pending Activation, but the activation email could not be sent. Use Resend Activation to try again.');}
    }

    public function resendRiderActivation(Request $r,RiderProfile $rider,RiderActivationService $activation)
    {
        $this->assertOwnedRider($r->user(),$rider);
        if($rider->account_status!=='pending_activation'||$rider->user->is_active)abort(422,'Activation can only be resent to a Rider who has not activated.');
        try{$activation->send($rider->load(['user','logisticsOwner']));return back()->with('success','A new activation email was sent to '.$rider->user->email.'. The previous link is invalid.');}
        catch(\Throwable $e){\Illuminate\Support\Facades\Log::warning('Rider activation email resend failed.',['rider_profile_id'=>$rider->id]);return back()->with('warning','The activation email could not be sent. Please try again later.');}
    }

    private function assertOwnedRider(User $owner,RiderProfile $rider):void
    {
        abort_unless($rider->logistics_user_id===$owner->id,404);
    }
    public function riderUpdate(Request $r,RiderProfile $rider){$this->assertOwnedRider($r->user(),$rider);$d=$r->validate(['account_status'=>'required|in:active,inactive,suspended','availability'=>'required|in:available,assigned,on_pickup,on_delivery,off_duty,unavailable','hub_id'=>'nullable|exists:logistics_hubs,id','vehicle_id'=>'nullable|exists:vehicles,id','emergency_contact_name'=>'nullable|string|max:100','emergency_contact_phone'=>'nullable|string|max:30','notes'=>'nullable|string|max:1000']);if($rider->account_status==='pending_activation')throw ValidationException::withMessages(['account_status'=>'Activate the Rider through the emailed link before changing account status.']);$hasActive=Shipment::where(fn($q)=>$q->where('pickup_rider_id',$rider->user_id)->orWhere('rider_id',$rider->user_id))->whereNotIn('status',['delivered','returned','completed'])->exists();if($hasActive&&$d['account_status']!=='active')throw ValidationException::withMessages(['account_status'=>'This Rider currently has an active assignment. Reassign or resolve it before changing the account status.']);if($d['account_status']!=='active')$d['availability']='unavailable';$rider->update($d);$rider->user->update(['is_active'=>$rider->account_status==='active']);return back()->with('success','Rider account and operational assignments updated.');}
    public function riderLicenseUpdate(Request $r,RiderProfile $rider){$this->assertOwnedRider($r->user(),$rider);$max=config('riders.document_max_kilobytes',5120);$d=$r->validate(['driver_license_number'=>['required','string','min:5','max:80','regex:/^[A-Za-z0-9 .\/-]+$/','unique:rider_profiles,driver_license_number,'.$rider->id],'driver_license_expires_at'=>'required|date','driver_license'=>"nullable|file|mimes:pdf,jpg,jpeg,png|max:$max",'driver_license_front'=>"nullable|file|mimes:pdf,jpg,jpeg,png|max:$max",'driver_license_back'=>"nullable|file|mimes:pdf,jpg,jpeg,png|max:$max"]);if(!$rider->driver_license_path&&!$rider->driver_license_front_path&&!$r->hasFile('driver_license')&&!$r->hasFile('driver_license_front'))throw ValidationException::withMessages(['driver_license'=>'A Driver License upload is required.']);$changes=['driver_license_number'=>strtoupper(trim($d['driver_license_number'])),'driver_license_expires_at'=>$d['driver_license_expires_at'],'driver_license_status'=>'pending_review','driver_license_rejection_reason'=>null,'driver_license_reviewed_by'=>null,'driver_license_reviewed_at'=>null,'availability'=>'unavailable'];if($r->hasFile('driver_license'))$changes['driver_license_path']=$r->file('driver_license')->store('rider-documents/licenses','local');if($r->hasFile('driver_license_front'))$changes['driver_license_front_path']=$r->file('driver_license_front')->store('rider-documents/licenses','local');if($r->hasFile('driver_license_back'))$changes['driver_license_back_path']=$r->file('driver_license_back')->store('rider-documents/licenses','local');$rider->update($changes);$rider->licenseAudits()->create(['actor_id'=>$r->user()->id,'event'=>'renewed','status'=>'pending_review','metadata'=>['expiration'=>$d['driver_license_expires_at']]]);return back()->with('success','License changes saved and returned to Pending Review.');}
    public function riderLicenseReview(Request $r,RiderProfile $rider){$this->assertOwnedRider($r->user(),$rider);$d=$r->validate(['status'=>'required|in:verified,rejected','reason'=>'nullable|required_if:status,rejected|string|max:1000']);if($d['status']==='verified'&&((!$rider->driver_license_path&&(!$rider->driver_license_front_path||!$rider->driver_license_back_path))||!$rider->driver_license_expires_at))throw ValidationException::withMessages(['status'=>'Complete license documents and expiration are required before verification.']);if($d['status']==='verified'&&$rider->driver_license_expires_at->lt(today()))throw ValidationException::withMessages(['status'=>'An expired license cannot be verified.']);$rider->update(['driver_license_status'=>$d['status'],'driver_license_rejection_reason'=>$d['reason']??null,'driver_license_reviewed_by'=>$r->user()->id,'driver_license_reviewed_at'=>now(),'availability'=>$d['status']==='verified'?'available':'unavailable']);$rider->licenseAudits()->create(['actor_id'=>$r->user()->id,'event'=>$d['status'],'status'=>$d['status'],'reason'=>$d['reason']??null]);return back()->with('success','Driver license review saved.');}
    public function riderLicenseFile(Request $r,RiderProfile $rider,string $side){$this->assertOwnedRider($r->user(),$rider);abort_unless(in_array($side,['front','back'],true),404);$path=$side==='front'?($rider->driver_license_front_path?:$rider->driver_license_path):$rider->driver_license_back_path;abort_unless($path&&Storage::disk('local')->exists($path),404);return Storage::disk('local')->download($path);}
    public function riderVehicleDocument(Request $r,RiderProfile $rider){$this->assertOwnedRider($r->user(),$rider);$path=$rider->or_cr_path;abort_unless($path&&Storage::disk('local')->exists($path),404);return Storage::disk('local')->download($path);}
    public function riderValidIdFile(Request $r,RiderProfile $rider){$this->assertOwnedRider($r->user(),$rider);$path=$rider->user?->valid_id_path;abort_unless($path&&Storage::disk('local')->exists($path),404);return Storage::disk('local')->download($path);}
    public function riderApplicationReview(Request $r,RiderProfile $rider){$d=$r->validate(['decision'=>'required|in:approved,rejected,needs_resubmission','reason'=>'nullable|required_unless:decision,approved|string|max:1000']);$user=$rider->user;abort_unless($user->registration_type==='rider'&&in_array($user->registration_status,['pending','needs_resubmission'],true),422);if($d['decision']==='approved'){if(!$rider->hasValidLicense()&&($rider->driver_license_status!=='pending_review'||!$rider->driver_license_expires_at||$rider->driver_license_expires_at->lt(today())||!$rider->driver_license_front_path||!$rider->driver_license_back_path||!$user->valid_id_path))throw ValidationException::withMessages(['decision'=>'Valid ID and complete, unexpired Driver license documents are required.']);$user->update(['registration_status'=>'approved','registration_review_notes'=>null,'registration_reviewed_by'=>$r->user()->id,'registration_reviewed_at'=>now(),'is_active'=>true]);$rider->update(['account_status'=>'active','availability'=>'off_duty','driver_license_status'=>'verified','driver_license_rejection_reason'=>null,'driver_license_reviewed_by'=>$r->user()->id,'driver_license_reviewed_at'=>now()]);$event='verified';$message='Your SHOPPICK Rider application has been approved.';}else{$user->update(['registration_status'=>$d['decision'],'registration_review_notes'=>$d['reason'],'registration_reviewed_by'=>$r->user()->id,'registration_reviewed_at'=>now(),'is_active'=>false]);$rider->update(['account_status'=>'inactive','availability'=>'unavailable','driver_license_status'=>$d['decision']==='rejected'?'rejected':'pending_review','driver_license_rejection_reason'=>$d['reason'],'driver_license_reviewed_by'=>$r->user()->id,'driver_license_reviewed_at'=>now()]);$event=$d['decision'];$message=$d['decision']==='rejected'?'Your SHOPPICK Rider application was not approved.':'SHOPPICK Logistics requested updated Rider application documents.';}$rider->licenseAudits()->create(['actor_id'=>$r->user()->id,'event'=>$event,'status'=>$rider->fresh()->driver_license_status,'reason'=>$d['reason']??null]);NotificationService::send($user->id,$message,$d['reason']??$message,'rider_application',$d['decision']==='approved'?route('rider.dashboard'):route('rider.application.status'),['rider_profile_id'=>$rider->id],'user');return back()->with('success','Rider application decision saved.');}
    public function riderMessage(Request $r,RiderProfile $rider){$this->assertOwnedRider($r->user(),$rider);$d=$r->validate(['message'=>'required|string|max:1000']);RiderMessage::create(['rider_id'=>$rider->user_id,'sender_id'=>$r->user()->id,'message'=>$d['message']]);NotificationService::send($rider->user_id,'Message from SHOPPICK Logistics',str($d['message'])->limit(140),'rider_message',route('rider.messages'),null,'message');return back()->with('success','Message sent to Rider.');}
    public function confirmRemittance(Request $r,Payment $payment){abort_unless($payment->method==='cod'&&$payment->remittance_status==='pending'&&$payment->collected_by,422);$payment->update(['remittance_status'=>'remitted','remitted_at'=>now(),'remitted_by'=>$r->user()->id]);NotificationService::send($payment->collected_by,'COD remittance confirmed',"Remittance for Order {$payment->order->order_number} was confirmed.",'cod_remittance',route('rider.cod'),['payment_id'=>$payment->id],'payment');return back()->with('success','COD remittance confirmed by Logistics.');}
    public function hubs(Request $r){$providerId=$r->attributes->get('logistics_provider')->id;$query=LogisticsHub::forProvider($providerId)->withCount(['shipments','riders','vehicles','scannerUsers'])->when($r->q,fn($q,$v)=>$q->where(fn($x)=>$x->where('name','like',"%$v%")->orWhere('code','like',"%$v%")->orWhere('address','like',"%$v%")))->when($r->status,fn($q,$v)=>$q->where('status',$v));$hubs=$query->latest()->get();$selected=$r->view?LogisticsHub::forProvider($providerId)->with(['shipments.store','riders.user','vehicles','scannerUsers','coverageAreas'])->withCount(['shipments','riders','vehicles','scannerUsers'])->find($r->view):null;if($r->view&&!$selected)abort(404);$logisticsUsers=User::where('is_active',true)->whereHas('roles',fn($q)=>$q->where('slug','logistics'))->whereHas('logisticsProviders',fn($q)=>$q->whereKey($providerId)->where('logistics_provider_user.is_active',true))->orderBy('name')->get();$coverageAreas=\App\Models\DeliveryArea::forProvider($providerId)->where('is_active',true)->orderBy('name')->get();return view('logistics.hubs',compact('hubs','selected','logisticsUsers','coverageAreas')); }
    public function hubStore(Request $r){LogisticsHub::create(['logistics_provider_id'=>$r->attributes->get('logistics_provider')->id]+$r->validate(['code'=>'required|string|max:30|unique:logistics_hubs','name'=>'required|string|max:100','address'=>'required|string|max:500','capacity'=>'nullable|integer|min:1','status'=>'required|in:active,inactive,maintenance','notes'=>'nullable|string|max:1000']));return back()->with('success','Hub saved.');}
    public function hubMove(Request $r,Shipment $shipment,OrderProgressService $progress){$d=$r->validate(['hub_id'=>'required|exists:logistics_hubs,id','type'=>'required|in:inbound,transfer,outbound','note'=>'nullable|string|max:500']);DB::transaction(function()use($r,$shipment,$d,$progress){$shipment=Shipment::whereKey($shipment->id)->lockForUpdate()->firstOrFail();DB::table('hub_movements')->insert(['shipment_id'=>$shipment->id,'from_hub_id'=>$shipment->current_hub_id,'to_hub_id'=>$d['hub_id'],'recorded_by'=>$r->user()->id,'type'=>$d['type'],'note'=>$d['note']??null,'moved_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);$shipment->update(['current_hub_id'=>$d['hub_id'],'status'=>$d['type']==='outbound'?'in_transit':'at_hub']);$shipment->events()->create(['actor_id'=>$r->user()->id,'status'=>$shipment->status,'location'=>LogisticsHub::find($d['hub_id'])->name,'note'=>$d['note']??ucfirst($d['type']).' Hub movement']);$progress->syncShipment($shipment);});return back()->with('success','Hub movement recorded.');}
    public function pod(Request $r){$query=ProofOfDelivery::with(['shipment.store','shipment.rider','submitter'])->when($r->q,fn($q,$v)=>$q->whereHas('shipment',fn($s)=>$s->where('shipment_number','like',"%$v%")->orWhereHas('store',fn($x)=>$x->where('name','like',"%$v%"))))->when($r->status,fn($q,$v)=>$q->where('status',$v));$summary=['pending'=>(clone $query)->where('status','pending')->count(),'approved'=>(clone $query)->where('status','approved')->count(),'rejected'=>(clone $query)->where('status','rejected')->count(),'total'=>(clone $query)->count()];$pods=$query->latest()->paginate(20)->withQueryString();$selected=$r->view?ProofOfDelivery::with(['shipment.store','shipment.rider','submitter'])->find($r->view):null;return view('logistics.pod',compact('pods','summary','selected')); }
    public function podReview(Request $r,ProofOfDelivery $pod){$d=$r->validate(['status'=>'required|in:approved,rejected','review_notes'=>'nullable|required_if:status,rejected|string|max:1000']);abort_unless($pod->status==='pending',422);$pod->update(['status'=>$d['status'],'review_notes'=>$d['review_notes']??null,'reviewed_by'=>$r->user()->id,'reviewed_at'=>now()]);NotificationService::send($pod->submitted_by,'Proof of Delivery '.$d['status'].'.',$d['status']==='rejected'?'Reason: '.$d['review_notes']:'Your POD was approved.','logistics',route('rider.shipments.show',$pod->shipment_id),['pod_id'=>$pod->id],'package');return back()->with('success','POD review saved.');}
    public function podFile(ProofOfDelivery $pod){abort_unless($pod->photo_path&&Storage::disk('local')->exists($pod->photo_path),404);return Storage::disk('local')->download($pod->photo_path);}
    public function billing(Request $r){$query=LogisticsInvoice::with(['shipment.order','shipment.store'])->when($r->q,fn($q,$v)=>$q->where('invoice_number','like',"%$v%")->orWhereHas('shipment',fn($s)=>$s->where('shipment_number','like',"%$v%")->orWhereHas('store',fn($x)=>$x->where('name','like',"%$v%"))))->when($r->status,fn($q,$v)=>$q->where('status',$v));$summary=['outstanding'=>(clone $query)->whereNotIn('status',['paid','void'])->sum('total'),'paid'=>(clone $query)->where('status','paid')->sum('total'),'pending'=>(clone $query)->whereIn('status',['draft','issued'])->sum('total'),'overdue'=>(clone $query)->where('status','overdue')->sum('total')];$invoices=$query->latest()->paginate(20)->withQueryString();$selected=$r->view?LogisticsInvoice::with(['shipment.order','shipment.store'])->find($r->view):null;return view('logistics.billing',compact('invoices','summary','selected')); }
    public function billingUpdate(Request $r,LogisticsInvoice $invoice){$d=$r->validate(['adjustments'=>'required|numeric|min:-999999|max:999999','status'=>'required|in:draft,issued,paid,overdue,void','notes'=>'nullable|string|max:1000']);$invoice->update(['adjustments'=>$d['adjustments'],'total'=>$invoice->delivery_fee+$d['adjustments'],'status'=>$d['status'],'notes'=>$d['notes']??null,'paid_at'=>$d['status']==='paid'?now():null]);return back()->with('success','Logistics invoice updated without changing the Buyer Order total.');}
    public function reports(Request $r){
        $r->validate(['date_from'=>'nullable|date','date_to'=>'nullable|date|after_or_equal:date_from','rider_id'=>'nullable|exists:users,id','shop_id'=>'nullable|exists:stores,id']);$from=$r->date_from?\Carbon\Carbon::parse($r->date_from)->startOfDay():now()->subDays(29)->startOfDay();$to=$r->date_to?\Carbon\Carbon::parse($r->date_to)->endOfDay():now()->endOfDay();if($from->diffInDays($to)>366)$from=$to->copy()->subDays(366)->startOfDay();
        $base=Shipment::query()->whereBetween('created_at',[$from,$to])->when($r->rider_id,fn($q,$v)=>$q->where('rider_id',$v))->when($r->shop_id,fn($q,$v)=>$q->where('store_id',$v));
        $shipments=(clone $base)->with(['rider','store','invoice'])->get();$delivered=$shipments->where('status','delivered');$eligible=$delivered->filter(fn($s)=>$s->estimated_delivery_at);$onTime=$eligible->filter(fn($s)=>$s->delivered_at->lte($s->estimated_delivery_at));
        $invoices=LogisticsInvoice::whereIn('shipment_id',$shipments->pluck('id'))->get();
        $data=['total'=>$shipments->count(),'delivered'=>$delivered->count(),'exceptions'=>$shipments->where('status','exception')->count(),'revenue'=>$invoices->sum('total'),'outstanding'=>$invoices->whereNotIn('status',['paid','void'])->sum('total'),'on_time_rate'=>$eligible->count()?round($onTime->count()/$eligible->count()*100,1):null,'eligible'=>$eligible->count(),'delayed'=>$eligible->count()-$onTime->count()];
        $days=collect(range(0,(int)$from->diffInDays($to)))->map(fn($n)=>$from->copy()->addDays($n));
        $charts=['labels'=>$days->map->format('M d'),'on_time'=>$days->map(fn($d)=>$eligible->filter(fn($s)=>$s->delivered_at->isSameDay($d))->pipe(fn($set)=>$set->count()?round($set->filter(fn($s)=>$s->delivered_at->lte($s->estimated_delivery_at))->count()/$set->count()*100,1):0)),'revenue'=>$days->map(fn($d)=>$invoices->filter(fn($i)=>$i->created_at->isSameDay($d))->sum('total'))];
        $lanes=$shipments->groupBy(fn($s)=>(data_get($s->pickup_address,'address','Shop')).' → '.(data_get($s->delivery_address,'city','Destination')))->map(fn($set)=>$set->where('status','exception')->count())->sortDesc()->take(8);
        $riderPerformance=$delivered->whereNotNull('rider_id')->groupBy('rider_id')->map(fn($set)=>['name'=>$set->first()->rider?->name??'Rider','delivered'=>$set->count(),'on_time'=>$set->filter(fn($s)=>$s->estimated_delivery_at&&$s->delivered_at->lte($s->estimated_delivery_at))->count()]);
        $aging=['Current'=>0,'1–30'=>0,'31–60'=>0,'61–90'=>0,'90+'=>0];foreach($invoices->whereNotIn('status',['paid','void']) as $i){$age=$i->created_at->diffInDays(now());$aging[$age<=0?'Current':($age<=30?'1–30':($age<=60?'31–60':($age<=90?'61–90':'90+')))] += $i->total;}
        $charts+=['lane_labels'=>$lanes->keys()->values(),'lane_delays'=>$lanes->values(),'rider_labels'=>$riderPerformance->pluck('name'),'rider_deliveries'=>$riderPerformance->pluck('delivered'),'rider_on_time'=>$riderPerformance->map(fn($x)=>$x['delivered']?round($x['on_time']/$x['delivered']*100,1):0)->values(),'aging_labels'=>collect($aging)->keys(),'aging_values'=>collect($aging)->values(),'accessorial_labels'=>['Approved Adjustments'],'accessorial_values'=>[$invoices->where('adjustments','>',0)->sum('adjustments')]];
        $riders=User::whereHas('roles',fn($q)=>$q->where('slug','rider'))->get();$shops=\App\Models\Store::orderBy('name')->get();
        $reportRows=$shipments->sortByDesc('created_at')->take(50);
        return view('logistics.reports',compact('data','charts','riders','shops','from','to','reportRows'));
    }
    public function ai(){ $insights=LogisticsInsight::latest()->paginate(20);return view('logistics.ai',compact('insights')); }
    public function analyze(){foreach(Shipment::whereNull('rider_id')->where('ready_at','<',now()->subHours(4))->get() as $s)LogisticsInsight::firstOrCreate(['type'=>'delay_risk','target_type'=>Shipment::class,'target_id'=>$s->id,'status'=>'generated'],['severity'=>'warning','title'=>'Shipment awaiting assignment','explanation'=>"{$s->shipment_number} has remained unassigned for more than four hours."]);return back()->with('success','Rule-based analysis completed using current shipment data.');}
    public function insight(Request $r,LogisticsInsight $insight){$d=$r->validate(['status'=>'required|in:viewed,accepted,dismissed,resolved']);$insight->update(['status'=>$d['status'],'acted_by'=>$r->user()->id,'acted_at'=>now()]);return back()->with('success','Insight decision recorded.');}
    public function notifications(Request $r){$items=$r->user()->notificationsData()->latest()->paginate(20);return view('logistics.notifications',compact('items'));}
    public function openNotification(Request $r,NotificationModel $notification){abort_unless($notification->user_id===$r->user()->id,404);$notification->markAsRead();return redirect($notification->link?:route('logistics.notifications'));}
    public function readAllNotifications(Request $r){$r->user()->notificationsData()->unread()->update(['read_at'=>now()]);return back()->with('success','Notifications marked as read.');}
    public function settings(){ $settings=LogisticsSetting::pluck('value','key');$hubs=LogisticsHub::where('status','active')->get();return view('logistics.settings',compact('settings','hubs')); }
    public function settingsUpdate(Request $r){$booleans=['require_pod','require_pod_review','pod_photo_required','recipient_name_required','buyer_tracking_visibility','delivery_status_notifications','notify_ready_pickup','notify_unassigned','notify_pickup_delay','notify_delivery_delay','notify_exception','notify_failed_delivery','notify_vehicle_maintenance','notify_hub_alert','notify_pod','notify_billing','notify_critical_ai','ai_rider_vehicle','ai_delay_risk','ai_cost_leak','ai_billing_anomaly','ai_explainability','ai_override_tracking'];$rules=['default_hub_id'=>'nullable|exists:logistics_hubs,id','pickup_wait_hours'=>'required|integer|min:1|max:168','hub_dwell_hours'=>'required|integer|min:1|max:168','delivery_delay_hours'=>'required|integer|min:1|max:720'];foreach($booleans as $key)$rules[$key]='required|boolean';$d=$r->validate($rules);foreach($d as $k=>$v)LogisticsSetting::updateOrCreate(['key'=>$k],['value'=>['value'=>$v],'updated_by'=>$r->user()->id]);return back()->with('success','Logistics settings saved.');}
}
